(function(){const A=[{"id":"sp8-morok-shipov","n":"Морок Шипов","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Чародей"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также опутывается колючими лозами: скорость 0 до конца её следующего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Шипов","orig":true,"pack":"spells8.js"},{"id":"sp8-otmetina-run","n":"Отметина Рун","l":0,"sc":"Ограждение","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 силовое поле","cl":["Изобретатель","Паладин","Следопыт"],"ds":"Вы отмечаете существо знаком (рун). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (силовое поле). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Рун","orig":true,"pack":"spells8.js"},{"id":"sp8-kara-vremeni","n":"Кара Времени","l":5,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 силовое поле","cl":["Изобретатель","Бард","Волшебник"],"ds":"Одно существо совершает спасбросок (Мудрость): 8к8 урона (силовое поле) при провале (и цель замедляется: не может совершать бонусных действий до конца своего следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Мудрость","atk":false,"mech":"Кара","theme":"Времени","orig":true,"pack":"spells8.js"},{"id":"sp8-strazh-teni","n":"Страж Тени","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 некротика","cl":["Следопыт","Колдун","Волшебник"],"ds":"Вы призываете крошечного духа (тени): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (некротика)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Тени","orig":true,"pack":"spells8.js"},{"id":"sp8-obereg-krovi","n":"Оберег Крови","l":0,"sc":"Некромантия","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Паладин","Волшебник"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «некротика», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Крови","orig":true,"pack":"spells8.js"},{"id":"sp8-svyatilische-molniy","n":"Святилище Молний","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кусочек янтаря.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Ловкость) — при провале они не может совершать реакции до начала своего следующего хода и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Ловкость","atk":false,"mech":"Святилище","theme":"Молний","orig":true,"pack":"spells8.js"},{"id":"sp8-vzryv-groma","n":"Взрыв Грома","l":3,"sc":"Воплощение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 звук","cl":["Чародей","Бард","Жрец"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Телосложение), получая 6к6 урона (звук) при провале (и цель отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Взрыв","theme":"Грома","orig":true,"pack":"spells8.js"},{"id":"sp8-volna-ineya","n":"Волна Инея","l":1,"sc":"Воплощение","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 холод","cl":["Чародей","Друид","Волшебник"],"ds":"Существа в конусе совершают спасбросок (Телосложение): при провале 2к6 урона (холод) и цель покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Волна","theme":"Инея","orig":true,"pack":"spells8.js"},{"id":"sp8-svyaz-plameni","n":"Связь Пламени","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Щепоть серы.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Изобретатель","Колдун","Следопыт"],"ds":"Вы вопрошаете пламя ближайшего очага (огонь помнит всё, что видел за последние сутки), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Пламени","orig":true,"pack":"spells8.js"},{"id":"sp8-potok-kostey","n":"Поток Костей","l":3,"sc":"Некромантия","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 колющий","cl":["Колдун","Жрец","Волшебник"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Телосложение): 7к6 урона (колющий) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Поток","theme":"Костей","orig":true,"pack":"spells8.js"},{"id":"sp8-uzy-pustoty","n":"Узы Пустоты","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 силовое поле","cl":["Чародей","Колдун","Следопыт"],"ds":"Узы (пустоты) охватывают существо: спасбросок (Харизма) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (силовое поле) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Харизма","atk":false,"mech":"Узы","theme":"Пустоты","orig":true,"pack":"spells8.js"},{"id":"sp8-raspad-zvezd","n":"Распад Звёзд","l":6,"sc":"Прорицание","t":"1 действие","r":"18 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 излучение","cl":["Бард","Чародей"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (излучение) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Звёзд","orig":true,"pack":"spells8.js"},{"id":"sp8-duh-razuma","n":"Дух Разума","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 психический","cl":["Колдун","Волшебник","Следопыт"],"ds":"Вы призываете духа (разума) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (психический). Иммунитет к урону «психический». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Разума","orig":true,"pack":"spells8.js"},{"id":"sp8-kleymo-yada","n":"Клеймо Яда","l":1,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 яд","cl":["Следопыт","Изобретатель","Паладин"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (яд), и цель совершает спасбросок (Телосложение) — при провале она отравлена до конца своего следующего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Клеймо","theme":"Яда","orig":true,"pack":"spells8.js"},{"id":"sp8-avatar-voln","n":"Аватар Волн","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 дробящий","cl":["Чародей","Жрец"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «дробящий», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (дробящий). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Волн","orig":true,"pack":"spells8.js"},{"id":"sp8-aura-vetra","n":"Аура Ветра","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 звук","cl":["Следопыт","Друид","Паладин"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «звук» и преимущество на спасброски от эффектов, из-за которых цель отталкивается на 4,5 м в выбранном вами направлении. Враг, начинающий ход в ауре, совершает спасбросок (Сила) или получает 2к6 урона (звук). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Аура","theme":"Ветра","orig":true,"pack":"spells8.js"},{"id":"sp8-golos-kamnya","n":"Голос Камня","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Чародей","Бард","Колдун"],"ds":"Ваш голос наполняется силой стихии (камня). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Камня","orig":true,"pack":"spells8.js"},{"id":"sp8-carstvo-duhov","n":"Царство Духов","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Благовония.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (духов) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Мудрость","atk":false,"mech":"Царство","theme":"Духов","orig":true,"pack":"spells8.js"},{"id":"sp8-perenos-mirazhey","n":"Перенос Миражей","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь по миражу на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Миражей","orig":true,"pack":"spells8.js"},{"id":"sp8-balzam-sveta","n":"Бальзам Света","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Следопыт"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «излучение» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Света","orig":true,"pack":"spells8.js"},{"id":"sp8-slovo-shipov","n":"Слово Шипов","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 колющий","cl":["Бард","Чародей"],"ds":"Вы произносите истинное слово (шипов). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (колющий) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Шипов","orig":true,"pack":"spells8.js"},{"id":"sp8-oblik-run","n":"Облик Рун","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 силовое поле","cl":["Изобретатель","Жрец","Паладин"],"ds":"Вы принимаете облик (рун): сопротивление урону «силовое поле» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (силовое поле). Попадание: цель получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Рун","orig":true,"pack":"spells8.js"},{"id":"sp8-cep-vremeni","n":"Цепь Времени","l":2,"sc":"Преобразование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 силовое поле","cl":["Бард","Изобретатель","Волшебник"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (силовое поле) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Мудрость) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":true,"mech":"Цепь","theme":"Времени","orig":true,"pack":"spells8.js"},{"id":"sp8-iskra-teni","n":"Искра Тени","l":0,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 некротика","cl":["Колдун","Волшебник","Друид"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (некротика). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Тени","orig":true,"pack":"spells8.js"},{"id":"sp8-stena-krovi","n":"Стена Крови","l":4,"sc":"Некромантия","t":"1 действие","r":"36 м","c":"ВСМ","m":"Капля вашей крови.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Стена (крови) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Телосложение): 5к8 урона (некротика) при провале (и цель не может восстанавливать хиты до конца своего следующего хода), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Стена","theme":"Крови","orig":true,"pack":"spells8.js"},{"id":"sp8-oruzhie-molniy","n":"Оружие Молний","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 электричество","cl":["Изобретатель","Паладин","Следопыт"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (электричество). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Ловкость): при провале она не может совершать реакции до начала своего следующего хода. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Молний","orig":true,"pack":"spells8.js"},{"id":"sp8-vspyshka-groma","n":"Вспышка Грома","l":0,"sc":"Воплощение","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 звук","cl":["Бард","Жрец","Чародей"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Телосложение), получая 1к6 урона (звук) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Телосложение","atk":false,"mech":"Вспышка","theme":"Грома","orig":true,"pack":"spells8.js"},{"id":"sp8-proklyatie-ineya","n":"Проклятие Инея","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 холод","cl":["Чародей","Друид","Паладин"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (холод), а в начале каждого её хода она бросает к4: на 1 она покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Инея","orig":true,"pack":"spells8.js"},{"id":"sp8-slepok-plameni","n":"Слепок Пламени","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Щепоть серы.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Колдун","Изобретатель","Волшебник"],"ds":"Вы создаёте немагический предмет из закалённого обсидиана, тёплого на ощупь размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Пламени","orig":true,"pack":"spells8.js"},{"id":"sp8-otmetina-kostey","n":"Отметина Костей","l":0,"sc":"Некромантия","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 колющий","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Вы отмечаете существо знаком (костей). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (колющий). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Костей","orig":true,"pack":"spells8.js"},{"id":"sp8-kara-pustoty","n":"Кара Пустоты","l":5,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 силовое поле","cl":["Чародей","Колдун","Волшебник"],"ds":"Одно существо совершает спасбросок (Харизма): 8к8 урона (силовое поле) при провале (и цель не может телепортироваться и перемещаться между планами до конца её следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Харизма","atk":false,"mech":"Кара","theme":"Пустоты","orig":true,"pack":"spells8.js"},{"id":"sp8-strazh-zvezd","n":"Страж Звёзд","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 излучение","cl":["Жрец","Друид","Волшебник"],"ds":"Вы призываете крошечного духа (звёзд): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (излучение)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Звёзд","orig":true,"pack":"spells8.js"},{"id":"sp8-obereg-razuma","n":"Оберег Разума","l":0,"sc":"Очарование","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Волшебник","Паладин","Жрец"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «психический», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Разума","orig":true,"pack":"spells8.js"},{"id":"sp8-svyatilische-yada","n":"Святилище Яда","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Жало пчелы.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Телосложение) — при провале они отравлена до конца своего следующего хода и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Телосложение","atk":false,"mech":"Святилище","theme":"Яда","orig":true,"pack":"spells8.js"},{"id":"sp8-vzryv-voln","n":"Взрыв Волн","l":3,"sc":"Вызов","t":"1 действие","r":"45 м","c":"ВСМ","m":"Морская ракушка.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 дробящий","cl":["Чародей","Жрец","Друид"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Сила), получая 6к6 урона (дробящий) при провале (и цель промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Взрыв","theme":"Волн","orig":true,"pack":"spells8.js"},{"id":"sp8-volna-vetra","n":"Волна Ветра","l":1,"sc":"Воплощение","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 звук","cl":["Чародей","Друид","Бард"],"ds":"Существа в конусе совершают спасбросок (Сила): при провале 2к6 урона (звук) и цель отталкивается на 4,5 м в выбранном вами направлении; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Волна","theme":"Ветра","orig":true,"pack":"spells8.js"},{"id":"sp8-svyaz-kamnya","n":"Связь Камня","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Кусочек гранита.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Изобретатель","Друид","Следопыт"],"ds":"Вы вопрошаете стену или скалу (камень помнит тысячу лет), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Камня","orig":true,"pack":"spells8.js"},{"id":"sp8-kokon-duhov","n":"Кокон Духов","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Бард","Колдун","Жрец"],"ds":"Кокон (духов) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Мудрость) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Кокон","theme":"Духов","orig":true,"pack":"spells8.js"},{"id":"sp8-pokrov-mirazhey","n":"Покров Миражей","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Кусочек стекла.","d":"1 час","conc":false,"rit":false,"dmg":"5 психический","cl":["Паладин","Волшебник","Изобретатель"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (психический); у вас сопротивление урону «психический». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Миражей","orig":true,"pack":"spells8.js"},{"id":"sp8-kolco-sveta","n":"Кольцо Света","l":6,"sc":"Воплощение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Святой символ.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 излучение","cl":["Жрец","Чародей"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Телосложение): при провале оно получает 6к8 урона (излучение), не проходит и излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Кольцо","theme":"Света","orig":true,"pack":"spells8.js"},{"id":"sp8-ubezhische-shipov","n":"Убежище Шипов","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Шип розы.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Следопыт","Паладин","Бард"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: шалаш из колючих лоз, раздвигающихся только перед вами и союзниками. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Шипов","orig":true,"pack":"spells8.js"},{"id":"sp8-chute-run","n":"Чутьё Рун","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Жрец","Изобретатель","Бард"],"ds":"Вы чувствуете надписи, магические знаки, глифы и ловушки-руны в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Рун","orig":true,"pack":"spells8.js"},{"id":"sp8-katastrofa-vremeni","n":"Катастрофа Времени","l":7,"sc":"Преобразование","t":"1 действие","r":"300 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 силовое поле","cl":["Бард","Волшебник"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Мудрость) — 12к6 урона (силовое поле) при провале (и цель замедляется: не может совершать бонусных действий до конца своего следующего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Мудрость","atk":false,"mech":"Катастрофа","theme":"Времени","orig":true,"pack":"spells8.js"},{"id":"sp8-opros-teni","n":"Опрос Тени","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Клочок чёрной ткани.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Следопыт","Колдун","Волшебник"],"ds":"Вы обращаетесь к стихии: вопрошаете тень места или предмета (она видела всё, что происходило рядом). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Тени","orig":true,"pack":"spells8.js"},{"id":"sp8-shag-krovi","n":"Шаг Крови","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 некротика","cl":["Колдун","Жрец","Следопыт"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Телосложение) или получает 1к6 урона (некротика). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Шаг","theme":"Крови","orig":true,"pack":"spells8.js"},{"id":"sp8-vlast-molniy","n":"Власть Молний","l":8,"sc":"Воплощение","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 электричество","cl":["Чародей","Волшебник"],"ds":"Вы повелеваете стихией (молний) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Ловкость), 6к10 урона (электричество) при провале и цель не может совершать реакции до начала своего следующего хода, половина при успехе.","save":"Ловкость","atk":false,"mech":"Власть","theme":"Молний","orig":true,"pack":"spells8.js"},{"id":"sp8-burya-groma","n":"Буря Грома","l":4,"sc":"Воплощение","t":"1 действие","r":"90 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 звук","cl":["Чародей","Бард","Жрец"],"ds":"Буря (грома) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Телосложение): 3к6 урона (звук) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Буря","theme":"Грома","orig":true,"pack":"spells8.js"},{"id":"sp8-sfera-ineya","n":"Сфера Инея","l":2,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кристалл льда.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 холод","cl":["Чародей","Волшебник","Друид"],"ds":"Сфера (инея) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Телосложение): 2к6 урона (холод) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Сфера","theme":"Инея","orig":true,"pack":"spells8.js"},{"id":"sp8-apokalipsis-plameni","n":"Апокалипсис Пламени","l":9,"sc":"Воплощение","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 огонь","cl":["Чародей","Волшебник"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Ловкость): 14к6 урона (огонь) плюс 14к6 силовым полем при провале (и цель загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Ловкость","atk":false,"mech":"Апокалипсис","theme":"Пламени","orig":true,"pack":"spells8.js"},{"id":"sp8-oblik-kostey","n":"Облик Костей","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 колющий","cl":["Колдун","Жрец","Паладин"],"ds":"Вы принимаете облик (костей): сопротивление урону «колющий» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (колющий). Попадание: цель становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Костей","orig":true,"pack":"spells8.js"},{"id":"sp8-cep-pustoty","n":"Цепь Пустоты","l":2,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 силовое поле","cl":["Чародей","Колдун","Волшебник"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (силовое поле) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Харизма) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Харизма","atk":true,"mech":"Цепь","theme":"Пустоты","orig":true,"pack":"spells8.js"},{"id":"sp8-iskra-zvezd","n":"Искра Звёзд","l":0,"sc":"Прорицание","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 излучение","cl":["Жрец","Бард","Волшебник"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (излучение). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Звёзд","orig":true,"pack":"spells8.js"},{"id":"sp8-stena-razuma","n":"Стена Разума","l":4,"sc":"Очарование","t":"1 действие","r":"36 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 психический","cl":["Чародей","Бард","Колдун"],"ds":"Стена (разума) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Интеллект): 5к8 урона (психический) при провале (и цель не может совершать реакции и совершает с помехой следующую проверку Интеллекта), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Интеллект","atk":false,"mech":"Стена","theme":"Разума","orig":true,"pack":"spells8.js"},{"id":"sp8-oruzhie-yada","n":"Оружие Яда","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 яд","cl":["Следопыт","Изобретатель","Паладин"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (яд). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Телосложение): при провале она отравлена до конца своего следующего хода. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Яда","orig":true,"pack":"spells8.js"},{"id":"sp8-vspyshka-voln","n":"Вспышка Волн","l":0,"sc":"Вызов","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 дробящий","cl":["Жрец","Чародей","Друид"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Сила), получая 1к6 урона (дробящий) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Сила","atk":false,"mech":"Вспышка","theme":"Волн","orig":true,"pack":"spells8.js"},{"id":"sp8-proklyatie-vetra","n":"Проклятие Ветра","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 звук","cl":["Следопыт","Чародей","Друид"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (звук), а в начале каждого её хода она бросает к4: на 1 она отталкивается на 4,5 м в выбранном вами направлении. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Ветра","orig":true,"pack":"spells8.js"},{"id":"sp8-slepok-kamnya","n":"Слепок Камня","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Кусочек гранита.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Друид","Волшебник"],"ds":"Вы создаёте немагический предмет из цельного камня размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Камня","orig":true,"pack":"spells8.js"},{"id":"sp8-maloe-chudo-duhov","n":"Малое Чудо Духов","l":0,"sc":"Вызов","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец","Колдун"],"ds":"Вы творите мелкое чудо: вызвать дух-светлячок, который переносит до 0,5 кг или шепчет вашим голосом в 9 м. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Духов","orig":true,"pack":"spells8.js"},{"id":"sp8-legion-mirazhey","n":"Легион Миражей","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Кусочек стекла.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Колдун","Следопыт","Волшебник"],"ds":"Появляются четыре духа (миражей): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «психический». Каждый атакует заклинанием 1,5 м на 2к6 урона (психический). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Миражей","orig":true,"pack":"spells8.js"},{"id":"sp8-pechat-sveta","n":"Печать Света","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Святой символ.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 излучение","cl":["Паладин","Жрец","Изобретатель"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Телосложение): 3к6 урона (излучение) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Печать","theme":"Света","orig":true,"pack":"spells8.js"},{"id":"sp8-kope-shipov","n":"Копьё Шипов","l":1,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 колющий","cl":["Друид","Бард","Чародей"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (колющий). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Шипов","orig":true,"pack":"spells8.js"},{"id":"sp8-dvoynik-run","n":"Двойник Рун","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 силовое поле","cl":["Изобретатель","Жрец","Бард"],"ds":"Вы создаёте двойника из камня, покрытого рунами. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (силовое поле) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Рун","orig":true,"pack":"spells8.js"},{"id":"sp8-potok-vremeni","n":"Поток Времени","l":3,"sc":"Преобразование","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 силовое поле","cl":["Бард","Изобретатель","Чародей"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Мудрость): 7к6 урона (силовое поле) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Поток","theme":"Времени","orig":true,"pack":"spells8.js"},{"id":"sp8-uzy-teni","n":"Узы Тени","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 некротика","cl":["Следопыт","Колдун","Паладин"],"ds":"Узы (тени) охватывают существо: спасбросок (Мудрость) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (некротика) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Узы","theme":"Тени","orig":true,"pack":"spells8.js"},{"id":"sp8-raspad-krovi","n":"Распад Крови","l":6,"sc":"Некромантия","t":"1 действие","r":"18 м","c":"ВСМ","m":"Капля вашей крови.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 некротика","cl":["Чародей","Колдун"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (некротика) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Крови","orig":true,"pack":"spells8.js"},{"id":"sp8-duh-molniy","n":"Дух Молний","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 электричество","cl":["Друид","Волшебник","Следопыт"],"ds":"Вы призываете духа (молний) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (электричество). Иммунитет к урону «электричество». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Молний","orig":true,"pack":"spells8.js"},{"id":"sp8-kleymo-groma","n":"Клеймо Грома","l":1,"sc":"Воплощение","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 звук","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (звук), и цель совершает спасбросок (Телосложение) — при провале она отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Клеймо","theme":"Грома","orig":true,"pack":"spells8.js"},{"id":"sp8-avatar-ineya","n":"Аватар Инея","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 холод","cl":["Чародей","Волшебник"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «холод», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (холод). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Инея","orig":true,"pack":"spells8.js"},{"id":"sp8-aura-plameni","n":"Аура Пламени","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 огонь","cl":["Паладин","Бард","Следопыт"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «огонь» и преимущество на спасброски от эффектов, из-за которых цель загорается. Враг, начинающий ход в ауре, совершает спасбросок (Ловкость) или получает 2к6 урона (огонь). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Ловкость","atk":false,"mech":"Аура","theme":"Пламени","orig":true,"pack":"spells8.js"},{"id":"sp8-chute-kostey","n":"Чутьё Костей","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Колдун","Жрец","Волшебник"],"ds":"Вы чувствуете останки, захоронения и нежить в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Костей","orig":true,"pack":"spells8.js"},{"id":"sp8-katastrofa-pustoty","n":"Катастрофа Пустоты","l":7,"sc":"Вызов","t":"1 действие","r":"300 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 силовое поле","cl":["Чародей","Колдун"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Харизма) — 12к6 урона (силовое поле) при провале (и цель не может телепортироваться и перемещаться между планами до конца её следующего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Харизма","atk":false,"mech":"Катастрофа","theme":"Пустоты","orig":true,"pack":"spells8.js"},{"id":"sp8-opros-zvezd","n":"Опрос Звёзд","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Бард","Жрец","Волшебник"],"ds":"Вы обращаетесь к стихии: вопрошаете звёзды над головой (они предсказывают ближайшее событие). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Звёзд","orig":true,"pack":"spells8.js"},{"id":"sp8-shag-razuma","n":"Шаг Разума","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 психический","cl":["Бард","Колдун","Волшебник"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Интеллект) или получает 1к6 урона (психический). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Интеллект","atk":false,"mech":"Шаг","theme":"Разума","orig":true,"pack":"spells8.js"},{"id":"sp8-vlast-yada","n":"Власть Яда","l":8,"sc":"Преобразование","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 яд","cl":["Колдун","Друид"],"ds":"Вы повелеваете стихией (яда) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Телосложение), 6к10 урона (яд) при провале и цель отравлена до конца своего следующего хода, половина при успехе.","save":"Телосложение","atk":false,"mech":"Власть","theme":"Яда","orig":true,"pack":"spells8.js"},{"id":"sp8-burya-voln","n":"Буря Волн","l":4,"sc":"Вызов","t":"1 действие","r":"90 м","c":"ВСМ","m":"Морская ракушка.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 дробящий","cl":["Чародей","Жрец","Друид"],"ds":"Буря (волн) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Сила): 3к6 урона (дробящий) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Сила","atk":false,"mech":"Буря","theme":"Волн","orig":true,"pack":"spells8.js"},{"id":"sp8-sfera-vetra","n":"Сфера Ветра","l":2,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Перо.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 звук","cl":["Чародей","Друид","Волшебник"],"ds":"Сфера (ветра) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Сила): 2к6 урона (звук) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Сфера","theme":"Ветра","orig":true,"pack":"spells8.js"},{"id":"sp8-apokalipsis-kamnya","n":"Апокалипсис Камня","l":9,"sc":"Преобразование","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 дробящий","cl":["Друид","Волшебник"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Сила): 14к6 урона (дробящий) плюс 14к6 силовым полем при провале (и цель сбивается с ног, если она Большая или меньше), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Сила","atk":false,"mech":"Апокалипсис","theme":"Камня","orig":true,"pack":"spells8.js"},{"id":"sp8-vrata-duhov","n":"Врата Духов","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Благовония.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 психический","cl":["Бард","Колдун","Жрец"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (духов). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (психический). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Духов","orig":true,"pack":"spells8.js"},{"id":"sp8-zavesa-mirazhey","n":"Завеса Миражей","l":2,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Куб с ребром 6 м заполняется завесой (миражей): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Интеллект) — при провале оно видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Интеллект","atk":false,"mech":"Завеса","theme":"Миражей","orig":true,"pack":"spells8.js"},{"id":"sp8-kasanie-sveta","n":"Касание Света","l":0,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 излучение","cl":["Жрец","Друид","Бард"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (излучение), и цель излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Света","orig":true,"pack":"spells8.js"},{"id":"sp8-tropa-shipov","n":"Тропа Шипов","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Шип розы.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"До 8 согласных существ отправляются в путь по корням: группа входит в одно дерево и выходит из другого того же вида. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Шипов","orig":true,"pack":"spells8.js"},{"id":"sp8-morok-run","n":"Морок Рун","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Жрец","Волшебник","Чародей"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Рун","orig":true,"pack":"spells8.js"},{"id":"sp8-otmetina-vremeni","n":"Отметина Времени","l":0,"sc":"Преобразование","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 силовое поле","cl":["Изобретатель","Паладин","Следопыт"],"ds":"Вы отмечаете существо знаком (времени). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (силовое поле). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Времени","orig":true,"pack":"spells8.js"},{"id":"sp8-kara-teni","n":"Кара Тени","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 некротика","cl":["Колдун","Изобретатель","Волшебник"],"ds":"Одно существо совершает спасбросок (Мудрость): 8к8 урона (некротика) при провале (и цель окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Мудрость","atk":false,"mech":"Кара","theme":"Тени","orig":true,"pack":"spells8.js"},{"id":"sp8-strazh-krovi","n":"Страж Крови","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Капля вашей крови.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 некротика","cl":["Колдун","Жрец","Следопыт"],"ds":"Вы призываете крошечного духа (крови): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (некротика)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Крови","orig":true,"pack":"spells8.js"},{"id":"sp8-obereg-molniy","n":"Оберег Молний","l":0,"sc":"Воплощение","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Волшебник","Паладин"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «электричество», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Молний","orig":true,"pack":"spells8.js"},{"id":"sp8-svyatilische-groma","n":"Святилище Грома","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Маленький колокольчик.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Изобретатель"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Телосложение) — при провале они отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Телосложение","atk":false,"mech":"Святилище","theme":"Грома","orig":true,"pack":"spells8.js"},{"id":"sp8-vzryv-ineya","n":"Взрыв Инея","l":3,"sc":"Воплощение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Кристалл льда.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 холод","cl":["Чародей","Друид","Бард"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Телосложение), получая 6к6 урона (холод) при провале (и цель покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Взрыв","theme":"Инея","orig":true,"pack":"spells8.js"},{"id":"sp8-volna-plameni","n":"Волна Пламени","l":1,"sc":"Воплощение","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 огонь","cl":["Чародей","Колдун","Изобретатель"],"ds":"Существа в конусе совершают спасбросок (Ловкость): при провале 2к6 урона (огонь) и цель загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Ловкость","atk":false,"mech":"Волна","theme":"Пламени","orig":true,"pack":"spells8.js"},{"id":"sp8-dvoynik-kostey","n":"Двойник Костей","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 колющий","cl":["Колдун","Жрец","Бард"],"ds":"Вы создаёте двойника из кости, крепкой как сталь. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (колющий) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Костей","orig":true,"pack":"spells8.js"},{"id":"sp8-potok-pustoty","n":"Поток Пустоты","l":3,"sc":"Вызов","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 силовое поле","cl":["Чародей","Колдун","Волшебник"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Харизма): 7к6 урона (силовое поле) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Харизма","atk":false,"mech":"Поток","theme":"Пустоты","orig":true,"pack":"spells8.js"},{"id":"sp8-uzy-zvezd","n":"Узы Звёзд","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 излучение","cl":["Бард","Жрец","Друид"],"ds":"Узы (звёзд) охватывают существо: спасбросок (Мудрость) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (излучение) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Узы","theme":"Звёзд","orig":true,"pack":"spells8.js"},{"id":"sp8-raspad-razuma","n":"Распад Разума","l":6,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 психический","cl":["Чародей","Бард"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (психический) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Разума","orig":true,"pack":"spells8.js"},{"id":"sp8-duh-yada","n":"Дух Яда","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Жало пчелы.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 яд","cl":["Следопыт","Колдун","Друид"],"ds":"Вы призываете духа (яда) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (яд). Иммунитет к урону «яд». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Яда","orig":true,"pack":"spells8.js"},{"id":"sp8-kleymo-voln","n":"Клеймо Волн","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 дробящий","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (дробящий), и цель совершает спасбросок (Сила) — при провале она промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Клеймо","theme":"Волн","orig":true,"pack":"spells8.js"},{"id":"sp8-avatar-vetra","n":"Аватар Ветра","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 звук","cl":["Чародей","Друид"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «звук», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (звук). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Ветра","orig":true,"pack":"spells8.js"},{"id":"sp8-aura-kamnya","n":"Аура Камня","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 дробящий","cl":["Друид","Паладин","Бард"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «дробящий» и преимущество на спасброски от эффектов, из-за которых цель сбивается с ног, если она Большая или меньше. Враг, начинающий ход в ауре, совершает спасбросок (Сила) или получает 2к6 урона (дробящий). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Аура","theme":"Камня","orig":true,"pack":"spells8.js"},{"id":"sp8-golos-duhov","n":"Голос Духов","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун","Жрец"],"ds":"Ваш голос наполняется силой стихии (духов). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Духов","orig":true,"pack":"spells8.js"},{"id":"sp8-carstvo-mirazhey","n":"Царство Миражей","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Кусочек стекла.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (миражей) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Интеллект","atk":false,"mech":"Царство","theme":"Миражей","orig":true,"pack":"spells8.js"},{"id":"sp8-perenos-sveta","n":"Перенос Света","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Следопыт"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь по лучу рассвета на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Света","orig":true,"pack":"spells8.js"},{"id":"sp8-balzam-shipov","n":"Бальзам Шипов","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «колющий» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Шипов","orig":true,"pack":"spells8.js"},{"id":"sp8-slovo-run","n":"Слово Рун","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 силовое поле","cl":["Жрец","Чародей"],"ds":"Вы произносите истинное слово (рун). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (силовое поле) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Рун","orig":true,"pack":"spells8.js"},{"id":"sp8-oblik-vremeni","n":"Облик Времени","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 силовое поле","cl":["Бард","Изобретатель","Волшебник"],"ds":"Вы принимаете облик (времени): сопротивление урону «силовое поле» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (силовое поле). Попадание: цель замедляется: не может совершать бонусных действий до конца своего следующего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Времени","orig":true,"pack":"spells8.js"},{"id":"sp8-cep-teni","n":"Цепь Тени","l":2,"sc":"Иллюзия","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 некротика","cl":["Колдун","Волшебник","Чародей"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (некротика) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Мудрость) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":true,"mech":"Цепь","theme":"Тени","orig":true,"pack":"spells8.js"},{"id":"sp8-iskra-krovi","n":"Искра Крови","l":0,"sc":"Некромантия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 некротика","cl":["Колдун","Жрец","Чародей"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (некротика). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Крови","orig":true,"pack":"spells8.js"},{"id":"sp8-stena-molniy","n":"Стена Молний","l":4,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 электричество","cl":["Чародей","Паладин","Волшебник"],"ds":"Стена (молний) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Ловкость): 5к8 урона (электричество) при провале (и цель не может совершать реакции до начала своего следующего хода), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Ловкость","atk":false,"mech":"Стена","theme":"Молний","orig":true,"pack":"spells8.js"},{"id":"sp8-oruzhie-groma","n":"Оружие Грома","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 звук","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (звук). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Телосложение): при провале она отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Грома","orig":true,"pack":"spells8.js"},{"id":"sp8-vspyshka-ineya","n":"Вспышка Инея","l":0,"sc":"Воплощение","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 холод","cl":["Чародей","Друид","Волшебник"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Телосложение), получая 1к6 урона (холод) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Телосложение","atk":false,"mech":"Вспышка","theme":"Инея","orig":true,"pack":"spells8.js"},{"id":"sp8-proklyatie-plameni","n":"Проклятие Пламени","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 огонь","cl":["Чародей","Колдун","Следопыт"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (огонь), а в начале каждого её хода она бросает к4: на 1 она загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Пламени","orig":true,"pack":"spells8.js"},{"id":"sp8-morok-kostey","n":"Морок Костей","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Колдун","Жрец","Волшебник"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Костей","orig":true,"pack":"spells8.js"},{"id":"sp8-otmetina-pustoty","n":"Отметина Пустоты","l":0,"sc":"Вызов","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 силовое поле","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Вы отмечаете существо знаком (пустоты). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (силовое поле). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Пустоты","orig":true,"pack":"spells8.js"},{"id":"sp8-kara-zvezd","n":"Кара Звёзд","l":5,"sc":"Прорицание","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 излучение","cl":["Бард","Жрец","Волшебник"],"ds":"Одно существо совершает спасбросок (Мудрость): 8к8 урона (излучение) при провале (и цель очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Мудрость","atk":false,"mech":"Кара","theme":"Звёзд","orig":true,"pack":"spells8.js"},{"id":"sp8-strazh-razuma","n":"Страж Разума","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 психический","cl":["Колдун","Волшебник","Следопыт"],"ds":"Вы призываете крошечного духа (разума): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (психический)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Разума","orig":true,"pack":"spells8.js"},{"id":"sp8-obereg-yada","n":"Оберег Яда","l":0,"sc":"Преобразование","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Паладин","Жрец"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «яд», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Яда","orig":true,"pack":"spells8.js"},{"id":"sp8-svyatilische-voln","n":"Святилище Волн","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Морская ракушка.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Паладин","Изобретатель"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Сила) — при провале они промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Сила","atk":false,"mech":"Святилище","theme":"Волн","orig":true,"pack":"spells8.js"},{"id":"sp8-vzryv-vetra","n":"Взрыв Ветра","l":3,"sc":"Воплощение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Перо.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 звук","cl":["Чародей","Друид","Бард"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Сила), получая 6к6 урона (звук) при провале (и цель отталкивается на 4,5 м в выбранном вами направлении) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Взрыв","theme":"Ветра","orig":true,"pack":"spells8.js"},{"id":"sp8-volna-kamnya","n":"Волна Камня","l":1,"sc":"Преобразование","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 дробящий","cl":["Изобретатель","Друид","Волшебник"],"ds":"Существа в конусе совершают спасбросок (Сила): при провале 2к6 урона (дробящий) и цель сбивается с ног, если она Большая или меньше; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Волна","theme":"Камня","orig":true,"pack":"spells8.js"},{"id":"sp8-svyaz-duhov","n":"Связь Духов","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Благовония.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Бард","Колдун","Жрец"],"ds":"Вы вопрошаете духа места (он отвечает загадками, но правдиво), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Духов","orig":true,"pack":"spells8.js"},{"id":"sp8-kokon-mirazhey","n":"Кокон Миражей","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Кокон (миражей) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Интеллект) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Кокон","theme":"Миражей","orig":true,"pack":"spells8.js"},{"id":"sp8-pokrov-sveta","n":"Покров Света","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Святой символ.","d":"1 час","conc":false,"rit":false,"dmg":"5 излучение","cl":["Паладин","Жрец","Волшебник"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (излучение); у вас сопротивление урону «излучение». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Света","orig":true,"pack":"spells8.js"},{"id":"sp8-kolco-shipov","n":"Кольцо Шипов","l":6,"sc":"Преобразование","t":"1 действие","r":"45 м","c":"ВСМ","m":"Шип розы.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 колющий","cl":["Друид","Чародей"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Сила): при провале оно получает 6к8 урона (колющий), не проходит и опутывается колючими лозами: скорость 0 до конца её следующего хода; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Сила","atk":false,"mech":"Кольцо","theme":"Шипов","orig":true,"pack":"spells8.js"},{"id":"sp8-ubezhische-run","n":"Убежище Рун","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Резец и кусочек кости.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Жрец","Паладин"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: кольцо рун, которое не пересекают нежить, исчадия и духи без вашего позволения. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Рун","orig":true,"pack":"spells8.js"},{"id":"sp8-chute-vremeni","n":"Чутьё Времени","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Бард","Изобретатель","Друид"],"ds":"Вы чувствуете следы недавних событий: где за последний час кто-то стоял, сидел или прошёл в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Времени","orig":true,"pack":"spells8.js"},{"id":"sp8-katastrofa-teni","n":"Катастрофа Тени","l":7,"sc":"Иллюзия","t":"1 действие","r":"300 м","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 некротика","cl":["Колдун","Волшебник"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Мудрость) — 12к6 урона (некротика) при провале (и цель окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Мудрость","atk":false,"mech":"Катастрофа","theme":"Тени","orig":true,"pack":"spells8.js"},{"id":"sp8-opros-krovi","n":"Опрос Крови","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Капля вашей крови.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Колдун","Жрец","Изобретатель"],"ds":"Вы обращаетесь к стихии: вопрошаете каплю крови (она отвечает о существе, которому принадлежала). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Крови","orig":true,"pack":"spells8.js"},{"id":"sp8-shag-molniy","n":"Шаг Молний","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 электричество","cl":["Изобретатель","Друид","Следопыт"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Ловкость) или получает 1к6 урона (электричество). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Ловкость","atk":false,"mech":"Шаг","theme":"Молний","orig":true,"pack":"spells8.js"},{"id":"sp8-vlast-groma","n":"Власть Грома","l":8,"sc":"Воплощение","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 звук","cl":["Чародей","Бард"],"ds":"Вы повелеваете стихией (грома) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Телосложение), 6к10 урона (звук) при провале и цель отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода, половина при успехе.","save":"Телосложение","atk":false,"mech":"Власть","theme":"Грома","orig":true,"pack":"spells8.js"},{"id":"sp8-burya-ineya","n":"Буря Инея","l":4,"sc":"Воплощение","t":"1 действие","r":"90 м","c":"ВСМ","m":"Кристалл льда.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 холод","cl":["Чародей","Друид","Волшебник"],"ds":"Буря (инея) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Телосложение): 3к6 урона (холод) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Буря","theme":"Инея","orig":true,"pack":"spells8.js"},{"id":"sp8-sfera-plameni","n":"Сфера Пламени","l":2,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Щепоть серы.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 огонь","cl":["Чародей","Колдун","Изобретатель"],"ds":"Сфера (пламени) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Ловкость): 2к6 урона (огонь) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Ловкость","atk":false,"mech":"Сфера","theme":"Пламени","orig":true,"pack":"spells8.js"},{"id":"sp8-slovo-kostey","n":"Слово Костей","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 колющий","cl":["Жрец","Колдун"],"ds":"Вы произносите истинное слово (костей). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (колющий) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Костей","orig":true,"pack":"spells8.js"},{"id":"sp8-oblik-pustoty","n":"Облик Пустоты","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 силовое поле","cl":["Колдун","Паладин","Волшебник"],"ds":"Вы принимаете облик (пустоты): сопротивление урону «силовое поле» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (силовое поле). Попадание: цель не может телепортироваться и перемещаться между планами до конца её следующего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Пустоты","orig":true,"pack":"spells8.js"},{"id":"sp8-cep-zvezd","n":"Цепь Звёзд","l":2,"sc":"Прорицание","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 излучение","cl":["Бард","Жрец","Волшебник"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (излучение) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Мудрость) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":true,"mech":"Цепь","theme":"Звёзд","orig":true,"pack":"spells8.js"},{"id":"sp8-iskra-razuma","n":"Искра Разума","l":0,"sc":"Очарование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 психический","cl":["Бард","Чародей","Колдун"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (психический). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Разума","orig":true,"pack":"spells8.js"},{"id":"sp8-stena-yada","n":"Стена Яда","l":4,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВСМ","m":"Жало пчелы.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 яд","cl":["Следопыт","Колдун","Друид"],"ds":"Стена (яда) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Телосложение): 5к8 урона (яд) при провале (и цель отравлена до конца своего следующего хода), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Стена","theme":"Яда","orig":true,"pack":"spells8.js"},{"id":"sp8-oruzhie-voln","n":"Оружие Волн","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 дробящий","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (дробящий). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Сила): при провале она промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Волн","orig":true,"pack":"spells8.js"},{"id":"sp8-vspyshka-vetra","n":"Вспышка Ветра","l":0,"sc":"Воплощение","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 звук","cl":["Чародей","Друид","Изобретатель"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Сила), получая 1к6 урона (звук) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Сила","atk":false,"mech":"Вспышка","theme":"Ветра","orig":true,"pack":"spells8.js"},{"id":"sp8-proklyatie-kamnya","n":"Проклятие Камня","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 дробящий","cl":["Друид","Волшебник","Чародей"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (дробящий), а в начале каждого её хода она бросает к4: на 1 она сбивается с ног, если она Большая или меньше. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Камня","orig":true,"pack":"spells8.js"},{"id":"sp8-slepok-duhov","n":"Слепок Духов","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Благовония.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун","Жрец"],"ds":"Вы создаёте немагический предмет из ткани из эктоплазмы, холодной и мягкой размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Духов","orig":true,"pack":"spells8.js"},{"id":"sp8-maloe-chudo-mirazhey","n":"Малое Чудо Миражей","l":0,"sc":"Иллюзия","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Вы творите мелкое чудо: создать иллюзорный образ размером до 30 см или изменить цвет и запах предмета на 1 минуту. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Миражей","orig":true,"pack":"spells8.js"},{"id":"sp8-legion-sveta","n":"Легион Света","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Святой символ.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 излучение","cl":["Жрец","Следопыт","Друид"],"ds":"Появляются четыре духа (света): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «излучение». Каждый атакует заклинанием 1,5 м на 2к6 урона (излучение). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Света","orig":true,"pack":"spells8.js"},{"id":"sp8-pechat-shipov","n":"Печать Шипов","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Шип розы.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 колющий","cl":["Паладин","Изобретатель","Волшебник"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Сила): 3к6 урона (колющий) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Печать","theme":"Шипов","orig":true,"pack":"spells8.js"},{"id":"sp8-kope-run","n":"Копьё Рун","l":1,"sc":"Ограждение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 силовое поле","cl":["Жрец","Изобретатель","Чародей"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (силовое поле). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Рун","orig":true,"pack":"spells8.js"},{"id":"sp8-dvoynik-vremeni","n":"Двойник Времени","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 силовое поле","cl":["Бард","Изобретатель","Паладин"],"ds":"Вы создаёте двойника из застывшего мгновения — предмет не стареет и не ломается. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (силовое поле) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Времени","orig":true,"pack":"spells8.js"}];const D=window.DATA=window.DATA||{};D.spells=D.spells||[];const ids=new Set(D.spells.map(s=>s.id));A.forEach(s=>{if(!ids.has(s.id))D.spells.push(s)});})();
